NO_PRODUCTION_WRITE = True

def build(task, reach_build=None, subset_build=None):
    n=task.n
    edges=task.edges
    outgoing=[[] for _ in range(n)]
    for u,v,w in edges:
        outgoing[u].append((v,w))
    closure=None
    sum_mask=None
    masks={}
    for excluded in (-1,):
        for source in range(n):
            paths=[0]*n
            if source!=excluded:
                paths[source]=1
            for u in range(source,n):
                if u==excluded:
                    continue
                for v,w in outgoing[u]:
                    if v!=excluded:
                        paths[v]|=(paths[u]<<w)
            masks[excluded,source]=tuple(paths)
    return (outgoing,closure,sum_mask,masks)

