    outgoing=[[] for _ in range(n)]
    for u,v,w in edges:
        outgoing[u].append((v,w))
    closure=(reach_build((n,tuple((u,v) for u,v,w in edges)))
             if reach_build is not None else None)
    sum_mask=(subset_build(tuple(w for u,v,w in edges))
              if subset_build is not None else None)
    masks={}
    for excluded in (-1,):
        for source in range(n):
            paths=[0]*n
            if source!=excluded:
                paths[source]=1
            for u in range(source,n):
                if u==excluded:
                    continue
                for v,w in outgoing[u]:
                    if v!=excluded:
                        paths[v]|=(paths[u]<<w)
