def answer(ctx,query):
    outgoing,closure,sum_mask,masks=ctx
    source,target,cost,excluded=query
    if source==excluded or target==excluded:
        return False
    if closure is not None and target not in closure[source]:
        return False
    if sum_mask is not None and ((sum_mask>>cost)&1)==0:
        return False
